            else str_closed.DisabledVote
        end as DisabledVotes

    from Users u

    left join Lateral (
        select string_agg(c.Name || ':' || b_count.cnt::text, ', ') as TopBadges -- ex: Gold:3, Bronze:12, Silver:7 
